import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_EXT_MARKER = re.compile(r"ext|x|#")
_ASCII_DIGITS = "0123456789"


def _parse_updated(value):
    text = value.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    raise ValueError(f"Unrecognized 'updated' value: {value!r}")


def _normalize_email(raw):
    text = raw.strip()
    if "<" in text and ">" in text:
        match = re.search(r"<([^<>]*)>", text)
        if match:
            text = match.group(1)
    text = text.strip().lower()
    if text.count("@") == 1:
        local, domain = text.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "")
            local = local.split("+", 1)[0]
            text = f"{local}@gmail.com"
    return text


def _is_valid_email(email):
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    if not local:
        return False
    return "." in domain and not domain.startswith(".") and not domain.endswith(".")


def _normalize_phone(raw):
    text = raw.lower()
    match = _EXT_MARKER.search(text)
    if match:
        text = text[:match.start()]
    digits = "".join(c for c in text if c in _ASCII_DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    text = raw.strip()
    match = re.fullmatch(r"([0-9]+)-[0-9]{4}", text)
    if match:
        text = match.group(1)
    if re.fullmatch(r"[0-9]{4}", text):
        text = "0" + text
    if re.fullmatch(r"[0-9]{5}", text):
        return text
    return ""


def _normalize_name(raw):
    text = raw.strip()
    if text.isupper() or text.islower():
        text = text.title()
    return text


def _parse_tags(raw):
    return {part.strip().lower() for part in re.split(r"[;,]", raw) if part.strip()}


def dedupe_contacts(rows):
    # Pass 1: normalize each row and drop rows with no valid email or phone.
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        email_ok = _is_valid_email(email)
        phone_ok = _is_valid_phone(phone)
        if not email_ok and not phone_ok:
            continue

        source = row.get("source", "").strip().lower()
        records.append({
            "index": idx,
            "first_name": _normalize_name(row.get("first_name", "")),
            "last_name": _normalize_name(row.get("last_name", "")),
            "zip": _normalize_zip(row.get("zip", "")),
            "email": email if email_ok else "",    # "" means no valid email
            "phone": phone if phone_ok else "",    # "" means no valid phone
            "source": source,
            "is_manual": source == "manual",
            "tags": _parse_tags(row.get("tags", "")),
            "opted_out": row.get("opted_out", "").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(row["updated"]),
        })

    # Pass 2: group matching records with union-find (handles transitivity).
    n = len(records)
    parent = list(range(n))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    by_email = {}
    by_phone_last = {}
    for i, rec in enumerate(records):
        if rec["email"]:
            if rec["email"] in by_email:
                union(by_email[rec["email"]], i)
            else:
                by_email[rec["email"]] = i
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].casefold())
            if key in by_phone_last:
                union(by_phone_last[key], i)
            else:
                by_phone_last[key] = i

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)
    # Members are appended in input order, so members[0] is each group's earliest row.
    ordered_groups = sorted(groups.values(), key=lambda members: members[0])

    # Pass 3: build one output record per person.
    def pick(members, field):
        candidates = [records[i] for i in members if records[i][field]]
        if not candidates:
            return ""
        # Prefer manual source, then latest updated, then earliest input row.
        best = max(
            candidates,
            key=lambda r: (r["is_manual"], r["updated"], -r["index"]),
        )
        return best[field]

    result = []
    for members in ordered_groups:
        group = [records[i] for i in members]

        tags = set()
        for rec in group:
            tags |= rec["tags"]

        latest = max(rec["updated"] for rec in group)

        result.append({
            "first_name": pick(members, "first_name"),
            "last_name": pick(members, "last_name"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(rec["opted_out"] for rec in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return result
